CREATE TABLE IF NOT EXISTS teams (id TEXT PRIMARY KEY, name TEXT NOT NULL, name_key TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, team_id TEXT NOT NULL, name TEXT NOT NULL, name_key TEXT NOT NULL, pin_salt TEXT NOT NULL, pin_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member', status TEXT NOT NULL DEFAULT 'pending', full_name TEXT NOT NULL DEFAULT '', default_company TEXT NOT NULL DEFAULT '', default_project TEXT NOT NULL DEFAULT '', employee_number TEXT NOT NULL DEFAULT '', machine TEXT NOT NULL DEFAULT '', machine_number TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_team_name ON users(team_id, name_key);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS entries (id TEXT PRIMARY KEY, team_id TEXT NOT NULL, user_id TEXT NOT NULL, entry_type TEXT NOT NULL DEFAULT 'worklog', company TEXT NOT NULL DEFAULT '', project TEXT NOT NULL, description TEXT NOT NULL, hours TEXT NOT NULL DEFAULT '0', kilometers TEXT NOT NULL DEFAULT '0', start_time TEXT NOT NULL DEFAULT '', end_time TEXT NOT NULL DEFAULT '', break_minutes TEXT NOT NULL DEFAULT '', report_slot TEXT NOT NULL DEFAULT 'auto', report_week_key TEXT NOT NULL DEFAULT '', work_date TEXT NOT NULL DEFAULT '', latitude TEXT, longitude TEXT, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_entries_team_created ON entries(team_id, created_at DESC);
CREATE TABLE IF NOT EXISTS photos (id TEXT PRIMARY KEY, entry_id TEXT NOT NULL, team_id TEXT NOT NULL, object_key TEXT NOT NULL, content_type TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_photos_entry ON photos(entry_id);
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, team_id TEXT NOT NULL, name TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS idx_projects_team_name ON projects(team_id, name);
